import{_ as c,C as i,o as n,c as l,ak as r,E as a,j as d,a as o}from"./chunks/framework.DxrHb2fb.js";const x=JSON.parse('{"title":"LoadingBar 加载条","description":"","frontmatter":{},"headers":[],"relativePath":"components/loading-bar.md","filePath":"components/loading-bar.md","lastUpdated":1790400917000}'),h={name:"components/loading-bar.md"};function s(b,t,g,u,p,m){const e=i("XhDemo");return n(),l("div",null,[t[0]||(t[0]=r('<h1 id="loadingbar-加载条" tabindex="-1">LoadingBar 加载条 <a class="header-anchor" href="#loadingbar-加载条" aria-label="Permalink to &quot;LoadingBar 加载条&quot;">​</a></h1><p>页面顶部的细进度线，表示正在导航或正在获取数据。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/loading-bar" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/loading-bar.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/loading-bar" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/loading-bar" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/loading-bar.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>进度条贴在视口顶边（见页面最上方）；不提供 value 即为不确定进度，宽度自行向前爬升，loading 切换为 false 后才到达终点并淡出</p>',5)),a(e,{src:"loading-bar/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;loading-bar&quot;</code>：<strong><code>root</code></strong> · <code>track</code> · <strong><code>range</code></strong> · <code>peg</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="确定进度" tabindex="-1">确定进度 <a class="header-anchor" href="#确定进度" aria-label="Permalink to &quot;确定进度&quot;">​</a></h3><p>传入 value 后由宿主决定，宽度按它显示，内部爬升不再介入；loading 仍然负责显示与收起</p>',6)),a(e,{src:"loading-bar/02-determinate"}),t[2]||(t[2]=d("h3",{id:"厚度",tabindex:"-1"},[o("厚度 "),d("a",{class:"header-anchor",href:"#厚度","aria-label":'Permalink to "厚度"'},"​")],-1)),t[3]||(t[3]=d("p",null,"height 数字按像素、字符串按任意 CSS 长度；进度段的颜色经语气或皮肤槽，不使用内联",-1)),a(e,{src:"loading-bar/03-appearance"}),t[4]||(t[4]=d("h3",{id:"关闭爬升",tabindex:"-1"},[o("关闭爬升 "),d("a",{class:"header-anchor",href:"#关闭爬升","aria-label":'Permalink to "关闭爬升"'},"​")],-1)),t[5]||(t[5]=d("p",null,"trickle 为 false 时进度条停在起步值 minimum 不动，向前推进全部由宿主收尾",-1)),a(e,{src:"loading-bar/04-trickle"}),t[6]||(t[6]=d("h3",{id:"颜色",tabindex:"-1"},[o("颜色 "),d("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[7]||(t[7]=d("p",null,"tone 只更换进度段的底色（取柔和档）；进度条本身是 fixed，这里改写为 absolute 并配一个相对定位的容器，六条才留在示例中而不是叠到页面顶边",-1)),a(e,{src:"loading-bar/05-tone"}),t[8]||(t[8]=d("h3",{id:"挂在局部",tabindex:"-1"},[o("挂在局部 "),d("a",{class:"header-anchor",href:"#挂在局部","aria-label":'Permalink to "挂在局部"'},"​")],-1)),t[9]||(t[9]=d("p",null,"进度条默认贴视口顶边，改写为 absolute 再套一个相对定位的容器，它就只贴该卡片的上沿",-1)),a(e,{src:"loading-bar/06-container"}),t[10]||(t[10]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>路由切换、整页数据刷新等用户不需要具体百分比的过程。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>进度确定且用户关心具体数值时，使用<a href="./progress">进度条</a>。</li><li>局部区域加载时，使用<a href="./skeleton">骨架屏</a>或<a href="./spinner">加载指示器</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>未提供确定进度时自动爬升（<code>trickle</code>）：先快后慢，不到 100%，收到完成信号后补满。</li><li><code>minimum</code> 是起始位置，让用户立即看到反应。</li><li>可以挂在局部容器上，不限于页面顶部。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与路由守卫配合：进入时启动，完成或失败时收起。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>失败时也要收起，停留在页面上的半截进度条比没有更差。</li><li>极快的请求可以延迟显示，避免闪烁。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>爬升到 100% 却尚未加载完成，用户会以为卡住。</li><li>同时挂多条。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-loading-bar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLoadingBarPeg</code> <code>XhLoadingBarRange</code> <code>XhLoadingBarRoot</code> <code>XhLoadingBarTrack</code></td></tr><tr><td>组合式函数</td><td><code>useLoadingBar</code></td></tr><tr><td>状态机</td><td><code>loadingBarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/loading-bar.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控进度值（0-100）。提供后即为确定进度：宽度按它显示，内部爬升停止。</td></tr><tr><td><code>defaultValue</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>加载开关：true 开始，false 结束（到达 100 后淡出归零）。只由宿主写入，无配套回调。</td></tr><tr><td><code>height</code></td><td><code>string | number</code></td><td></td><td>进度条厚度：数字按像素，字符串按任意 CSS 长度。默认 2px。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定进度段使用哪族颜色。需要其他颜色时修改皮肤槽 --xh-loading-bar-range。</td></tr><tr><td><code>trickle</code></td><td><code>boolean</code></td><td></td><td>不确定进度时自行向前爬升，默认开启。关闭则停在起步值等待宿主收尾。</td></tr><tr><td><code>trickleSpeed</code></td><td><code>number</code></td><td></td><td>爬升节拍毫秒，默认 200；&lt;=0 或非有限数等同于关闭爬升。</td></tr><tr><td><code>minimum</code></td><td><code>number</code></td><td></td><td>起步值，默认 8：开始加载时先跳到该值。</td></tr><tr><td><code>fadeDuration</code></td><td><code>number</code></td><td></td><td>到达 100 之后的淡出时长毫秒，写进皮肤的淡出时长槽 --xh-loading-bar-fade，不给按退场令牌；淡出过渡真正播完才归零并收起。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;LoadingBarTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: LoadingBarValueChangeDetails) =&gt; void</code></td><td></td><td>进度值变化。不确定进度下每爬升一步、到达 100、归零各通知一次。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>LoadingBarValueChangeDetails</code></td><td>进度值变化；detail 为 <code>{ value: number }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLoadingBarRoot</code></td><td><code>default</code></td><td><code>LoadingBarRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLoadingBarRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;LoadingBarRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>track</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>range</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>peg</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>loading</code> · <code>finishing</code></p><p><strong>事件</strong>：<code>LOADING.START</code> · <code>LOADING.END</code> · <code>TRICKLE.SYNC</code> · <code>after.trickleSpeed</code> · <code>FADE.DONE</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>LoadingBarPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前显示的进度值（0-100，已夹取），也是 range 的宽度百分比。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td>进度条是否显示：idle 之外都显示。</td></tr><tr><td><code>indeterminate</code></td><td><code>boolean</code></td><td>不确定进度：未提供 value，宽度自行爬升，不输出 aria-valuenow。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRangeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPegProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>进度段末端的亮边。纯装饰，作者不渲染它时进度条照常成立。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#progressbar" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations.root</td></tr><tr><td><code>root</code></td><td><code>aria-valuemax</code></td><td>String(LOADING_BAR_MAX)</td></tr><tr><td><code>root</code></td><td><code>aria-valuemin</code></td><td>&#39;0&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-valuenow</code></td><td>String(value) | undefined</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;progressbar&#39;</td></tr><tr><td><code>peg</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/loading-bar.css</code> 使用 <code>[data-scope=&quot;loading-bar&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-indeterminate</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>track</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>range</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>peg</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-loading-bar-fade</code></td><td><code>root</code></td><td><code>transition</code></td><td><code>default</code></td><td><code>--xh-motion-duration-exit</code></td><td>loading-bar 的 root 部件 transition 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-layer</code></td><td><code>root</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-layer-sticky</code></td><td>loading-bar 的 root 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-peg-fg</code></td><td><code>peg</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-loading-bar-range</code></td><td>loading-bar 的 peg 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-peg-w</code></td><td><code>peg</code></td><td><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-space-8</code></td><td>loading-bar 的 peg 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-range</code></td><td><code>peg</code><br><code>range</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tone-soft</code></td><td>loading-bar 的 peg、range 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-speed</code></td><td><code>range</code></td><td><code>transition</code></td><td><code>default</code></td><td><code>--xh-motion-duration-move</code></td><td>loading-bar 的 range 部件 transition 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-track</code></td><td><code>track</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>loading-bar 的 track 部件 background 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：指示与换位 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>可覆盖的动效槽：<code>--xh-loading-bar-fade</code> · <code>--xh-loading-bar-speed</code>。</p><p><code>opacity</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p>',59))])}const k=c(h,[["render",s]]);export{x as __pageData,k as default};
